INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was sind aushangpflichtige Gesetze für einen Fachinformatiker?', 2, '[{"text": "Gesetze, die Arbeitnehmerrechte schützen", "correct": true, "because": "Informieren über Rechte und Pflichten"}, {"text": "Marketingvorschriften", "correct": false, "because": "Kein Bezug zu Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen aushangpflichtige Gesetze?', 3, '[{"text": "Arbeitnehmer über Rechte informieren", "correct": true, "because": "Schutz und Transparenz"}, {"text": "IT-Systeme optimieren", "correct": false, "because": "Kein technisches Ziel"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gesetze gehören zu den aushangpflichtigen Gesetzen?', 5, '[{"text": "Arbeitszeitgesetz (ArbZG)", "correct": true, "because": "Regelt Arbeitszeiten"}, {"text": "Allgemeines Gleichbehandlungsgesetz (AGG)", "correct": true, "because": "Schutz vor Diskriminierung"}, {"text": "Marketinggesetz", "correct": false, "because": "Kein Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Mutterschutzgesetz ist aushangpflichtig bei mehr als drei Frauen im Betrieb. b) Es gilt nur für IT-Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Betriebe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich als Fachinformatiker bei aushangpflichtigen Gesetzen?', 4, '[{"text": "Arbeitsschutzvorschriften", "correct": false, "because": "Müssen beachtet werden"}, {"text": "Zugänglichkeit für Mitarbeiter", "correct": false, "because": "Pflicht"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Arbeitszeitgesetz aushangpflichtig ist?', 2, '[{"text": "Ja", "correct": true, "because": "§ 16 ArbZG fordert Aushang"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz muss ein Fachinformatiker aushängen, wenn Jugendliche beschäftigt sind?', 3, '[{"text": "Jugendarbeitsschutzgesetz", "correct": true, "because": "Schutz für unter 18-Jährige"}, {"text": "Mindestlohngesetz", "correct": false, "because": "Nicht spezifisch für Jugendliche"}, {"text": "Datenschutzgesetz", "correct": false, "because": "Kein direkter Aushang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung der Aushangpflicht?', 5, '[{"text": "Zugänglichkeit sicherstellen", "correct": true, "because": "Für alle einsehbar"}, {"text": "Aktualität gewährleisten", "correct": true, "because": "Aktuelle Version nötig"}, {"text": "Softwareentwicklung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Fachinformatiker muss das ArbSchG aushängen. b) Es gilt nur für Büros. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Arbeitsplätze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei aushangpflichtigen Gesetzen unwichtig?', 4, '[{"text": "Aktualität", "correct": false, "because": "Muss aktuell sein"}, {"text": "Zugänglichkeit", "correct": false, "because": "Pflicht"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Fachinformatiker das AGG aushängen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 12 AGG fordert Aushang"}, {"text": "Nein", "correct": false, "because": "Pflicht für alle Betriebe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einhaltung der Aushangpflicht?', 4, '[{"text": "Rechtssicherheit", "correct": true, "because": "Vermeidet Bußgelder"}, {"text": "Informierte Mitarbeiter", "correct": true, "because": "Klarheit über Rechte"}, {"text": "Schnellere IT-Prozesse", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass aushangpflichtige Gesetze nur für große Firmen gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ab erstem Mitarbeiter"}, {"text": "Ja", "correct": false, "because": "Unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei aushangpflichtigen Gesetzen?', 3, '[{"text": "Zugänglichkeit", "correct": true, "because": "Für alle einsehbar"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das ArbZG ist aushangpflichtig. b) Es gilt nur für IT-Bereiche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Bereiche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Missachtung der Aushangpflicht?', 5, '[{"text": "Bußgelder", "correct": true, "because": "Bis zu 5.000 €"}, {"text": "Schadensersatzrisiko", "correct": true, "because": "Bei Schäden durch Unwissenheit"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei der Aushangpflicht?', 3, '[{"text": "Digitalen Zugang sicherstellen", "correct": true, "because": "z.B. Intranet"}, {"text": "Hardware warten", "correct": false, "because": "Kein direkter Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Aushangpflicht digital erfüllt werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Intranet, wenn zugänglich"}, {"text": "Nein", "correct": false, "because": "Flexibel erfüllbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Aushangpflicht für Fachinformatiker?', 4, '[{"text": "Berufsbildungsgesetz", "correct": true, "because": "§ 106 BBiG für Auszubildende"}, {"text": "Datenschutzgesetz", "correct": false, "because": "Kein Aushang"}, {"text": "Urlaubsgesetz", "correct": false, "because": "Nicht primär"}]');
